const basket=[];const cards=[...document.querySelectorAll('.dataset')];const basketBox=document.querySelector('#basket');const basketList=document.querySelector('#basketList');const basketCount=document.querySelectorAll('[data-basket-count]');function renderBasket(){basketCount.forEach(x=>x.textContent=basket.length);basketList.innerHTML=basket.length?basket.map(x=>`<div class="basket-item">${x}</div>`).join(''):'<p>No datasets yet.</p>';}document.querySelectorAll('[data-add]').forEach(btn=>btn.addEventListener('click',()=>{const title=btn.closest('.dataset').dataset.title;if(!basket.includes(title))basket.push(title);renderBasket();basketBox.classList.add('open');}));document.querySelector('#basketToggle').addEventListener('click',()=>basketBox.classList.toggle('open'));document.querySelector('#basketClose').addEventListener('click',()=>basketBox.classList.remove('open'));document.querySelector('#datasetSearch').addEventListener('input',e=>{const q=e.target.value.toLowerCase();cards.forEach(c=>c.hidden=!c.innerText.toLowerCase().includes(q));});document.querySelector('#domainFilter').addEventListener('change',e=>{const v=e.target.value;cards.forEach(c=>c.hidden=v&&c.dataset.domain!==v);});document.querySelector('#startProject').addEventListener('click',()=>{const q=document.querySelector('#researchQuestion').value.trim();alert(q?`Project starter would create an INQETRA project from:

${q}`:'Enter a research question or problem first.');});renderBasket();